 * @param {number} actor
 * @param {number} targetId
 * @param {string} recipeKey
 */
export function brewAtAlchemyBench(world, actor, targetId, recipeKey) {
  if (!world.has(actor, Inventory)) {
    world.emit?.("alchemy:result", {
      actor,
      targetId,
      result: "no_inventory",
      recipeKey: String(recipeKey || ""),
    });
    return;
  }

